actions.payload:
tell application "Calendar"
    set newEvent to make new event at end of events of calendar "Home" with properties {summary:"$TITLE", start date:date "$START_DATE", end date:date "$END_DATE"}
end tell

tell application "Reminders"
    set newReminder to make new reminder with properties {name:"$TITLE"}
end tell

tell application "Notes"
    make new note at folder "Notes" with properties {name:"$TITLE", body:"$BODY"}
end tell
